<?php
defined('ABSPATH') || exit;
class SMF_Courier_Timeline {
    const TABLE_SUFFIX='smf_courier_events';
    const PROCESSING_TTL=300;
    const MAX_ATTEMPTS=5;
    const SCHEMA_VERSION='2.7';
    public static function init(){add_action('rest_api_init',array(__CLASS__,'ensure_table'));add_filter('rest_pre_dispatch',array(__CLASS__,'dedupe_webhook'),10,3);add_filter('rest_post_dispatch',array(__CLASS__,'mark_webhook_result'),10,3);add_action('woocommerce_order_status_changed',array(__CLASS__,'status_changed'),20,4);add_action('woocommerce_order_status_smf-delivered',array(__CLASS__,'mark_delivered_at'),5);add_action('woocommerce_admin_order_data_after_billing_address',array(__CLASS__,'order_timeline'),20);}
    public static function ensure_table(){global $wpdb;$table=$wpdb->prefix.self::TABLE_SUFFIX;if(get_option('smf_courier_events_schema','')===self::SCHEMA_VERSION&&$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$table))===$table)return;require_once ABSPATH.'wp-admin/includes/upgrade.php';$charset=$wpdb->get_charset_collate();dbDelta("CREATE TABLE $table (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,provider varchar(32) NOT NULL DEFAULT 'generic',event_id varchar(128) NOT NULL,event_hash char(64) NOT NULL,order_id bigint(20) unsigned DEFAULT NULL,status varchar(64) DEFAULT NULL,payload longtext DEFAULT NULL,response_code smallint(5) unsigned DEFAULT NULL,result varchar(20) NOT NULL DEFAULT 'received',attempts smallint(5) unsigned NOT NULL DEFAULT 0,last_error text DEFAULT NULL,next_retry_at datetime DEFAULT NULL,last_attempt_at datetime DEFAULT NULL,received_at datetime NOT NULL,processed_at datetime DEFAULT NULL,PRIMARY KEY(id),UNIQUE KEY event_hash(event_hash),KEY provider_event(provider,event_id),KEY order_id(order_id),KEY received_at(received_at),KEY retry_state(result,next_retry_at),KEY attempt_state(attempts,result)) $charset;");update_option('smf_courier_events_schema',self::SCHEMA_VERSION,false);}
    private static function table(){global $wpdb;return $wpdb->prefix.self::TABLE_SUFFIX;}
    private static function signature_valid($request,$raw){$secret=trim((string)get_option('smf_courier_webhook_secret',''));if($secret==='')return false;$sig=$request->get_header('x-smf-signature');if(!$sig)$sig=$request->get_header('x-webhook-signature');if(!$sig)return false;if(stripos($sig,'sha256=')===0)$sig=substr($sig,7);return hash_equals(hash_hmac('sha256',$raw,$secret),trim($sig));}
    public static function webhook_signature_valid($request){return self::signature_valid($request,$request->get_body());}
    private static function request_identity($request){$raw=$request->get_body();$data=json_decode($raw,true);if(!is_array($data))return false;$event_id='';foreach(array('event_id','webhook_id','eventId','id') as $key){if(isset($data[$key])&&is_scalar($data[$key])&&trim((string)$data[$key])!==''){$event_id=sanitize_text_field((string)$data[$key]);break;}}if($event_id==='')$event_id=trim((string)$request->get_header('x-smf-event-id'));if($event_id==='')$event_id=trim((string)$request->get_header('x-event-id'));$provider=!empty($data['provider'])?sanitize_key($data['provider']):sanitize_key((string)get_option('smf_courier_provider','generic'));$provider=$provider?:'generic';$order_id=!empty($data['order_id'])?absint($data['order_id']):0;$status=!empty($data['status'])?sanitize_key((string)$data['status']):(!empty($data['delivery_status'])?sanitize_key((string)$data['delivery_status']):'');if($event_id!==''){$identity_key=$provider.'|'.$event_id;$hash=hash('sha256',$identity_key);}else{$hash=hash('sha256',$provider.'|raw|'.$raw);$event_id=$hash;}return array('raw'=>$raw,'data'=>$data,'event_id'=>substr($event_id,0,128),'hash'=>$hash,'provider'=>$provider,'order_id'=>$order_id?:null,'status'=>$status?:null);}
    private static function identity_conflict($existing,$identity){$incoming_order=$identity['order_id']?(int)$identity['order_id']:0;$stored_order=$existing->order_id?(int)$existing->order_id:0;if($incoming_order&&$stored_order&&$incoming_order!==$stored_order)return true;$incoming_status=(string)$identity['status'];$stored_status=(string)$existing->status;if($incoming_status!==''&&$stored_status!==''&&$incoming_status!==$stored_status)return true;return false;}
    private static function conflict_response($identity,$existing){return new WP_REST_Response(array('ok'=>false,'duplicate'=>true,'conflict'=>true,'event_id'=>$identity['event_id'],'order_id'=>$existing->order_id?(int)$existing->order_id:$identity['order_id'],'reason'=>'event_identity_conflict'),409);}
    private static function backoff($attempt){$delays=array(300,900,1800,3600,7200);$index=max(0,min(count($delays)-1,$attempt-1));return $delays[$index];}
    private static function failure_reason($response){if(is_wp_error($response)){return substr('wp_error: '.implode('; ',array_map('strval',$response->get_error_messages())),0,1000);}if($response instanceof WP_HTTP_Response){$data=$response->get_data();if(is_array($data)&&!empty($data['code']))return substr((string)$data['code'].' '.(!empty($data['message'])?(string)$data['message']:''),0,1000);if(is_array($data)&&!empty($data['reason']))return substr((string)$data['reason'],0,1000);}return 'Webhook processing returned an unsuccessful HTTP response.';}
    public static function dedupe_webhook($result,$server,$request){if((string)$request->get_route()!=='/sync-meta-flow/v1/courier/webhook'||strtoupper($request->get_method())!=='POST')return $result;$identity=self::request_identity($request);if(!$identity||!self::signature_valid($request,$identity['raw']))return $result;self::ensure_table();global $wpdb;$table=self::table();$existing=$wpdb->get_row($wpdb->prepare('SELECT id,result,order_id,status,received_at,attempts FROM '.$table.' WHERE event_hash=%s LIMIT 1',$identity['hash']));if($existing&&self::identity_conflict($existing,$identity))return self::conflict_response($identity,$existing);if($existing&&$existing->result==='processed')return new WP_REST_Response(array('ok'=>true,'duplicate'=>true,'event_id'=>$identity['event_id'],'order_id'=>$existing->order_id?(int)$existing->order_id:$identity['order_id'],'status'=>$existing->status,'result'=>'processed'),200);if($existing&&$existing->result==='ignored')return new WP_REST_Response(array('ok'=>true,'duplicate'=>true,'ignored'=>true,'event_id'=>$identity['event_id'],'order_id'=>$existing->order_id?(int)$existing->order_id:$identity['order_id'],'status'=>$existing->status,'result'=>'ignored'),200);if($existing&&$existing->result==='processing'){$age=time()-strtotime($existing->received_at);if($age>=self::PROCESSING_TTL){$wpdb->query($wpdb->prepare("UPDATE $table SET result='received',response_code=NULL,processed_at=NULL,next_retry_at=NULL,last_error=%s,received_at=%s WHERE id=%d AND result='processing'",'stale_processing_recovered',current_time('mysql'),(int)$existing->id));}else{return new WP_REST_Response(array('ok'=>false,'duplicate'=>true,'event_id'=>$identity['event_id'],'result'=>'processing'),409);}}elseif($existing&&$existing->result==='failed'){$now=current_time('mysql');$wpdb->query($wpdb->prepare("UPDATE $table SET result='received',response_code=NULL,processed_at=NULL,next_retry_at=NULL,received_at=%s WHERE id=%d AND result='failed' AND attempts<%d",$now,(int)$existing->id,self::MAX_ATTEMPTS));}elseif(!$existing){$wpdb->query($wpdb->prepare("INSERT IGNORE INTO $table (provider,event_id,event_hash,order_id,status,payload,received_at,result) VALUES (%s,%s,%s,%s,%s,%s,%s,'received')",$identity['provider'],$identity['event_id'],$identity['hash'],$identity['order_id'],$identity['status'],wp_json_encode($identity['data']),current_time('mysql')));}$claimed=$wpdb->query($wpdb->prepare("UPDATE $table SET result='processing',attempts=attempts+1,last_attempt_at=%s,received_at=%s WHERE event_hash=%s AND result='received' AND attempts<%d",current_time('mysql'),current_time('mysql'),$identity['hash'],self::MAX_ATTEMPTS));if((int)$claimed!==1){$row=$wpdb->get_row($wpdb->prepare('SELECT result,order_id,status,attempts FROM '.$table.' WHERE event_hash=%s LIMIT 1',$identity['hash']));if($row&&$row->result==='processed')return new WP_REST_Response(array('ok'=>true,'duplicate'=>true,'event_id'=>$identity['event_id'],'order_id'=>$row->order_id?(int)$row->order_id:$identity['order_id'],'status'=>$row->status,'result'=>'processed'),200);if($row&&$row->result==='failed')return new WP_REST_Response(array('ok'=>false,'duplicate'=>true,'event_id'=>$identity['event_id'],'result'=>'failed','attempts'=>(int)$row->attempts),429);if($row&&$row->result==='ignored')return new WP_REST_Response(array('ok'=>true,'duplicate'=>true,'ignored'=>true,'event_id'=>$identity['event_id'],'result'=>'ignored'),200);return new WP_REST_Response(array('ok'=>false,'duplicate'=>true,'event_id'=>$identity['event_id'],'result'=>'processing'),409);}return $result;}
    public static function mark_webhook_ignored($request){$identity=self::request_identity($request);if(!$identity)return false;self::ensure_table();global $wpdb;return (bool)$wpdb->query($wpdb->prepare("UPDATE ".self::table()." SET response_code=200,result='ignored',processed_at=%s,next_retry_at=NULL,last_error=NULL WHERE event_hash=%s AND result='processing'",current_time('mysql'),$identity['hash']));}
    public static function mark_webhook_result($response,$server,$request){if((string)$request->get_route()!=='/sync-meta-flow/v1/courier/webhook'||strtoupper($request->get_method())!=='POST')return $response;$identity=self::request_identity($request);if(!$identity)return $response;self::ensure_table();global $wpdb;$code=method_exists($response,'get_status')?(int)$response->get_status():500;$success=$code>=200&&$code<300;$result=$success?'processed':'failed';$row=$wpdb->get_row($wpdb->prepare('SELECT attempts FROM '.self::table().' WHERE event_hash=%s LIMIT 1',$identity['hash']));$attempts=$row?(int)$row->attempts:1;$error=$success?null:self::failure_reason($response);$next=null;if(!$success&&$attempts<self::MAX_ATTEMPTS)$next=gmdate('Y-m-d H:i:s',time()+self::backoff($attempts));if(!$success&&$attempts>=self::MAX_ATTEMPTS)$error='max_attempts_exhausted: '.$error;$wpdb->query($wpdb->prepare('UPDATE '.self::table().' SET response_code=%d,result=%s,processed_at=%s,last_error=%s,next_retry_at=%s WHERE event_hash=%s AND result=\'processing\'',$code,$result,current_time('mysql'),$error,$next,$identity['hash']));return $response;}
    public static function record_retry_failure($id,$message){global $wpdb;self::ensure_table();$row=$wpdb->get_row($wpdb->prepare('SELECT attempts FROM '.self::table().' WHERE id=%d LIMIT 1',absint($id)));if(!$row)return false;$attempts=(int)$row->attempts+1;$next=null;$error=substr((string)$message,0,1000);if($attempts<self::MAX_ATTEMPTS)$next=gmdate('Y-m-d H:i:s',time()+self::backoff($attempts));else$error='max_attempts_exhausted: '.$error;return (bool)$wpdb->query($wpdb->prepare("UPDATE ".self::table()." SET attempts=%d,result='failed',response_code=NULL,processed_at=%s,last_error=%s,next_retry_at=%s WHERE id=%d AND result IN ('received','processing')",$attempts,current_time('mysql'),$error,$next,absint($id)));}
    public static function get_retryable_events($limit=20){global $wpdb;self::ensure_table();$limit=max(1,min(100,absint($limit)));return $wpdb->get_results($wpdb->prepare("SELECT * FROM ".self::table()." WHERE result='failed' AND attempts<%d AND next_retry_at IS NOT NULL AND next_retry_at<=UTC_TIMESTAMP() ORDER BY next_retry_at ASC,id ASC LIMIT %d",self::MAX_ATTEMPTS,$limit));}
    public static function claim_retry($id){global $wpdb;self::ensure_table();return (bool)$wpdb->query($wpdb->prepare("UPDATE ".self::table()." SET result='received',next_retry_at=NULL,processed_at=NULL WHERE id=%d AND result='failed' AND attempts<%d AND next_retry_at IS NOT NULL AND next_retry_at<=UTC_TIMESTAMP()",absint($id),self::MAX_ATTEMPTS));}
    public static function health(){global $wpdb;self::ensure_table();$table=self::table();return array('failed'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $table WHERE result='failed'"),'retryable'=>(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $table WHERE result='failed' AND attempts<%d AND next_retry_at IS NOT NULL",self::MAX_ATTEMPTS)),'processing'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $table WHERE result='processing'"),'exhausted'=>(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $table WHERE result='failed' AND attempts>=%d",self::MAX_ATTEMPTS)));}
    public static function status_changed($order_id,$old_status,$new_status,$order){$provider=(string)$order->get_meta('_smf_courier_provider');if($provider==='')return;global $wpdb;$event_id='status-'.absint($order_id).'-'.sanitize_key($new_status).'-'.gmdate('YmdHis');$hash=hash('sha256',$event_id.'|'.$order_id.'|'.$new_status);$wpdb->query($wpdb->prepare("INSERT IGNORE INTO ".self::table()." (provider,event_id,event_hash,order_id,status,payload,received_at,result,processed_at) VALUES (%s,%s,%s,%d,%s,%s,%s,'processed',%s)",$provider,$event_id,$hash,absint($order_id),sanitize_key($new_status),wp_json_encode(array('source'=>'woocommerce','old_status'=>$old_status,'new_status'=>$new_status)),current_time('mysql'),current_time('mysql')));}
    public static function mark_delivered_at($order_id){$order=wc_get_order($order_id);if($order){$existing=$order->get_meta('_smf_delivered_at');if(!$existing||!is_numeric($existing)){$order->update_meta_data('_smf_delivered_at',time());$order->save();}}}
    public static function get_events($order_id,$limit=20){global $wpdb;$limit=max(1,min(100,absint($limit)));return $wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::table().' WHERE order_id=%d ORDER BY received_at DESC,id DESC LIMIT %d',absint($order_id),$limit));}
    public static function order_timeline($order){if(!current_user_can('manage_woocommerce'))return;$events=self::get_events($order->get_id(),20);if(!$events)return;echo '<div style="margin-top:12px;padding:12px;border:1px solid #ddd;background:#fff"><strong>Courier Event Timeline</strong><div style="margin-top:8px">';foreach($events as $event){$label=$event->status?ucwords(str_replace(array('_','-'),' ',$event->status)):'Event';$when=mysql2date(get_option('date_format').' '.get_option('time_format'),$event->received_at);$state=$event->result==='failed'?'Failed':($event->result==='processed'?'Processed':($event->result==='ignored'?'Ignored':($event->result==='processing'?'Processing':'Received')));$meta='attempts: '.(int)$event->attempts;if(!empty($event->last_error))$meta.=' · '.substr((string)$event->last_error,0,180);echo '<div style="padding:7px 0;border-top:1px solid #eee"><strong>'.esc_html($label).'</strong> · '.esc_html($state).'<br><span class="description">'.esc_html($event->provider).' · '.esc_html($when).' · '.esc_html($meta).'</span></div>';}echo '</div></div>';}
}
